class Solution {
public:
    int minimumSum(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n), right(n);
        left[0] = nums[0];
        for (int i = 1; i < n; i++) left[i] = min(left[i - 1], nums[i]);
        right[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) right[i] = min(right[i + 1], nums[i]);
        int ans = 1e9;
        for (int j = 1; j < n - 1; j++) {
            if (left[j - 1] < nums[j] && right[j + 1] < nums[j]) {
                ans = min(ans, left[j - 1] + nums[j] + right[j + 1]);
            }
        }
        return ans == 1e9 ? -1 : ans;
    }
};

class Solution {
    public int minimumSum(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        left[0] = nums[0];
        for (int i = 1; i < n; i++) left[i] = Math.min(left[i - 1], nums[i]);
        right[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) right[i] = Math.min(right[i + 1], nums[i]);
        int ans = Integer.MAX_VALUE;
        for (int j = 1; j < n - 1; j++) {
            if (left[j - 1] < nums[j] && right[j + 1] < nums[j]) {
                ans = Math.min(ans, left[j - 1] + nums[j] + right[j + 1]);
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

