var minimumSum = function(nums) {
    const n = nums.length;
    const left = new Int32Array(n);
    const right = new Int32Array(n);
    left[0] = nums[0];
    for (let i = 1; i < n; i++) left[i] = Math.min(left[i - 1], nums[i]);
    right[n - 1] = nums[n - 1];
    for (let i = n - 2; i >= 0; i--) right[i] = Math.min(right[i + 1], nums[i]);
    let ans = Infinity;
    for (let j = 1; j < n - 1; j++) {
        if (left[j - 1] < nums[j] && right[j + 1] < nums[j]) {
            const curr = left[j - 1] + nums[j] + right[j + 1];
            if (curr < ans) ans = curr;
        }
    }
    return ans === Infinity ? -1 : ans;
};
